if (!insomnia.variables.get('booking_id')) {
  const scheme = insomnia.variables.get('scheme') || 'http';
  const domain = insomnia.variables.get('domain') || '127.0.0.1';
  const port = insomnia.variables.get('port') || '3000';
  const prefix = insomnia.variables.get('api_prefix') || '/api/v1';
  const url = scheme + '://' + domain + ':' + port + prefix;
  const resp = await insomnia.sendRequest({
    url: url + '/bookings?limit=1&status=confirmed',
    method: 'GET',
    headers: { accept: 'application/json' }
  });
  const body = JSON.parse(resp.body);
  const bookings = body.data || [];
  if (bookings.length === 0) throw new Error('No booking available (bookings list is empty)');
  insomnia.environment.set('booking_id', bookings[0].id);
  console.log('booking_id = ' + bookings[0].id);
}

const scheme = insomnia.variables.get('scheme') || 'http';
const domain = insomnia.variables.get('domain') || '127.0.0.1';
const port = insomnia.variables.get('port') || '3000';
const prefix = insomnia.variables.get('api_prefix') || '/api/v1';
const urlFor = function (p) { return scheme + '://' + domain + ':' + port + prefix + p; };
async function getJson(url) {
  const resp = await insomnia.sendRequest({ url: url, method: 'GET', headers: { accept: 'application/json' } });
  return JSON.parse(resp.body);
}

async function main() {
  const routes = (await getJson(urlFor('/routes?limit=50'))).data || [];
  if (routes.length === 0) throw new Error('No routes found to create a booking');
  const route = routes[Math.floor(Math.random() * routes.length)];
  const stops = (await getJson(urlFor('/routes/' + route.id + '/stops?limit=20'))).data || [];
  if (stops.length < 2) throw new Error('Route ' + route.id + ' has fewer than two stops');
  insomnia.environment.set('route_id', route.id);
  insomnia.environment.set('from_stop_id', stops[0].id);
  insomnia.environment.set('to_stop_id', stops[stops.length - 1].id);
  console.log('route_id = ' + route.id + ', from = ' + stops[0].id + ', to = ' + stops[stops.length - 1].id);
}
await main();

